237	static void vmap_perf_init_once(void)
238	{
239	    uint32_t a;
240	    uint32_t b;
241	    int i;
242	
243	    if (s_pf_ready) {
244	        return;
245	    }
246	    s_pf_ready = true;
247	
248	    VMAP_PERF_ITM_LAR = VMAP_PERF_LAR_KEY;
249	    VMAP_PERF_DWT_LAR = VMAP_PERF_LAR_KEY;
250	    VMAP_PERF_DWT_DEMCR |= (1u << 24);   /* TRCENA */
251	    VMAP_PERF_DWT_CTRL |= 1u;            /* CYCCNTENA */
252	
253	    a = VMAP_PERF_DWT_CYCCNT;
254	    for (i = 0; i < 64; i++) {
255	        __asm__ volatile("nop");
256	    }
257	    b = VMAP_PERF_DWT_CYCCNT;
258	    s_pf_usable = (b != a);
259	
260	    if (!s_pf_usable) {
261	        syslog(LOG_WARNING, "[vperf] DWT CYCCNT 不可用，分段计时停用\n");
262	    } else {
263	        vmap_perf_psram_probe();
264	        vmap_perf_cache_probe();
265	#if VMAP_RENDER_PRIM_SELF
266	        {
267	            /* 多边形定点自测：确定性输入，两个固件的数字可直接对减 */
268	            vmap_render_polyself_t st;
269	
270	            vmap_render_polyselftest(&st);
271	            syslog(LOG_INFO,
272	                "[vperf] polyself pass=%u fpcyc=%u fpcross=%u intcyc=%u intcross=%u",
273	                (unsigned)st.pass, (unsigned)st.fp_cyc, (unsigned)st.fp_cross,
274	                (unsigned)st.in_cyc, (unsigned)st.in_cross);
275	        }
276	#endif
277	    }
278	}
