499	static void vmap_perf_cache_probe(void)
500	{
501	    const uint32_t ccr = VMAP_PERF_CACHE_CCR;
502	
503	    /* 实测原值：全树没有任何代码碰过这个外设（grep hwp_cache-> 零命中）。
504	     * 首次上板读到的是 **ccr=0x00000000（irange=0 drange=0）**，而且整帧
505	     * I/D 计数器都是 0 ⇒ 缓存既不覆盖代码也不覆盖数据，**代码是从 PSRAM 裸取指**。
506	     * 详见 docs/map/perf/MEASUREMENTS.md §2.6。 */
507	    syslog(LOG_INFO,
508	        "[vperf] cache ccr=0x%08x irange=%u drange=%u cnten=%u",
509	        (unsigned)ccr,
510	        (unsigned)((ccr >> 16) & 0x1fu), (unsigned)((ccr >> 24) & 0x1fu),
511	        (unsigned)(ccr & 1u));
512	
513	    /* **只打开计数器，不改缓存行为。**
514	     *
515	     * 实验做过了（2026-09-25）：把 IRANGE 设成 MPI1（只缓存代码区、DRANGE 保持 0，
516	     * 因为代码只读、缓存只读数据没有一致性问题，而这个外设又没有 clean/invalidate
517	     * 接口 ⇒ 不该缓存数据）——结果是 **cyc_tile 90.56M vs 不缓存 89.69M，没有变化**，
518	     * 而计数器同时显示取指 miss 率只有 **0.068%**（391,198,596 次访问 / 266,570 次 miss）。
519	     * ⇒ **未开缓存时顺序预取已经把紧凑代码喂饱了，取指不是瓶颈**，所以不设 IRANGE。
520	     * 详见 docs/map/perf/MEASUREMENTS.md §2.6。 */
521	    VMAP_PERF_CACHE_CCR = (ccr & ~VMAP_PERF_CACHE_CNTCLR) | VMAP_PERF_CACHE_CNTEN
522	        | VMAP_PERF_CACHE_CNTCLR;
523	}
