526	 * @brief SLOW gap 时点名"谁在运行 / 谁就绪"。
527	 *
528	 * 形态 C（用户 2026-09-26 现场）缺的就是这一条：探针能说"停了 1.61 秒"，但说不出
529	 * 那 1.61 秒是谁占着 CPU。判据来自另两条探针的组合 —— 喂狗线程（prio 180）没报
530	 * late ⇒ 不是全局冻结/长时间关中断；而 idle 心跳陈旧 ⇒ CPU 从没空过 ⇒ 是某个
531	 * prio ≥ 100 的任务在持续空转。所以这里把 Ready/Running 的任务列出来点名
532	 * （`state`: 2=Ready 3=Running，与 coredump 快照的 `snap … st=` 同一口径）。
533	 */
534	static void vmap_perf_dump_runnable(void)
535	{
536	    struct myvendor_schedmon_snap_s snap;
537	    char buf[176];
538	    size_t n = 0u;
539	    uint16_t i;
540	
541	    if (!myvendor_schedmon_snap_copy(&snap)) {
542	        syslog(LOG_WARNING, "[vperf] SLOW: schedmon 快照不可用\n");
543	        return;
544	    }
545	
546	    for (i = 0u; i < snap.ntask && n + 24u < sizeof(buf); i++) {
547	        const struct myvendor_schedmon_task_s * t = &snap.task[i];
548	        const int w = snprintf(buf + n, sizeof(buf) - n, "%s%s(pid%d,pri%d)",
549	                               n ? "," : "", t->name, (int)t->pid, (int)t->pri);
550	
551	        if (t->state != 2u && t->state != 3u) {
552	            continue;
553	        }
554	        if (w <= 0) {
555	            break;
556	        }
557	        n += (size_t)w;
558	    }
559	
560	    syslog(LOG_WARNING, "[vperf] SLOW: 运行/就绪 = %s\n", n ? buf : "(无)");
561	}
