void vmap_track_refresh(vmap_track_t * track)
{
    uint32_t render_rev;
    bool km_dirty;
    bool painted;
    bool full_paint;
    bool dirty_valid = false;
    lv_area_t dirty;

    if (!track || !track->view) {
