    /** 上次提出重规划的时刻（ticks）与"抑制中"日志的限频时刻 —— 见
     *  VMAP_NAV_REROUTE_MIN_INTERVAL_MS：偏航判定在稀几何下会每帧成立。 */
    uint32_t last_reroute_tick;
