    nav->opposite_accum_m = 0.0;
    nav->junction_off_accum_m = 0.0;
    nav->last_passed_maneuver = UINT32_MAX;
    nav->need_reroute = false;
    nav->reroute_reason = VMAP_ROUTE_REROUTE_NONE;
    nav->has_prev = false;
